const _wh = $('Webhook Cloud').first().json || {};
const d = _wh.body || _wh;
const t = $('Tools Cloud').first().json || {};
const findings = [];

if (!t.nextcloud || !t.nextcloud.reachable) findings.push({level:'CRIT', text:'Nextcloud no responde'});
if (!t.immich || !t.immich.reachable) findings.push({level:'CRIT', text:'Immich no responde'});
if (!t.immich_ml_node2 || !t.immich_ml_node2.reachable) findings.push({level:'WARN', text:'immich-ml en Nodo 2 no responde (puede estar apagado)'});
if (!(t.backups_count > 0)) findings.push({level:'WARN', text:'Sin backups-visibles en /mnt/node2-storage/backups-compose'});
if (!findings.length) findings.push({level:'OK', text:'Nube, Immich y backups bajo demanda disponibles'});

const severity = findings.some(f => f.level === 'CRIT') ? 'CRIT'
  : findings.length ? 'WARN' : 'OK';
const evidence = JSON.stringify({nextcloud:t.nextcloud, immich:t.immich, immich_ml:t.immich_ml_node2, backups:t.backups_recent}).slice(0, 4500);
const prompt = `Eres Agent-Cloud, empleado especializado de HomeLab Corp.
Tu jefe es HomeLab-Director. Analiza esta evidencia en tiempo real y entrega un
informe ejecutivo de 3 a 5 líneas en español, con hallazgos concretos y
recomendaciones de solo lectura. No reinicies nada, no borres nada, no expongas
secretos. Si no hay problemas, dilo explícitamente.

EVIDENCIA:
${evidence}

HALLAZGOS DETERMINISTAS:
${JSON.stringify(findings)}
`;
return [{json: {
  employee: 'Agent-Cloud',
  severity,
  quality_score: 0.9,
  findings,
  evidence,
  prompt,
  directive: d.directive || '',
  task_id: d.task_id || null,
  round_id: d.round_id || null,
  tool_data: t
}}];

const a = $('Analizar Cloud').first().json || {};
const l = $('LLM Cloud').first().json || {};
const choices = l.choices || [];
const text = ((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
return [{json: {
  employee: a.employee,
  severity: a.severity,
  quality_score: a.quality_score,
  summary: (text || a.summary || 'Sin hallazgos').slice(0, 2500),
  findings: a.findings || [],
  evidence: a.evidence || '',
  directive: a.directive || '',
  task_id: a.task_id || null,
  round_id: a.round_id || null
}}];

const r = $('Rendir cuentas Cloud').first().json || {};
const d = $('Redactar informe Cloud').first().json || {};
return [{json: {...d, report_id: r.report_id || null, ledger_ok: !!r.ok}}];
